CREATE TABLE IF NOT EXISTS public.agent_configuration_catalog(
 key text PRIMARY KEY, definition jsonb NOT NULL, updated_at timestamptz NOT NULL DEFAULT now()
);
ALTER TABLE public.agent_configuration_catalog ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.agent_configuration_catalog FROM PUBLIC,anon,authenticated;
GRANT SELECT,INSERT,UPDATE,DELETE ON public.agent_configuration_catalog TO service_role;

CREATE OR REPLACE FUNCTION public.get_workspace_agent_bundle(p_workspace_id uuid)
RETURNS jsonb LANGUAGE sql STABLE SECURITY INVOKER SET search_path=public,pg_temp AS $$
 SELECT jsonb_build_object(
  'workspaceId',a.workspace_id,'version',a.config_version,'schemaVersion',2,'updatedAt',a.updated_at,
  'fields',(SELECT jsonb_agg(c.definition ORDER BY c.definition->>'group',c.key) FROM public.agent_configuration_catalog c),
  'values',(SELECT jsonb_object_agg(c.key,c.definition->'default') FROM public.agent_configuration_catalog c)
       || coalesce(a.configuration->'runtime'->'values','{}'::jsonb))
 FROM public.workspace_agents a WHERE a.workspace_id=p_workspace_id AND a.status='active';
$$;
REVOKE ALL ON FUNCTION public.get_workspace_agent_bundle(uuid) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.get_workspace_agent_bundle(uuid) TO service_role;

CREATE OR REPLACE FUNCTION public.initialize_workspace_agent_configuration(p_workspace_id uuid,p_values jsonb)
RETURNS boolean LANGUAGE plpgsql SECURITY INVOKER SET search_path=public,pg_temp AS $$
DECLARE a public.workspace_agents%ROWTYPE;
BEGIN
 SELECT * INTO a FROM public.workspace_agents WHERE workspace_id=p_workspace_id FOR UPDATE;
 IF NOT FOUND OR a.config_version<>0 THEN RETURN false; END IF;
 PERFORM public.publish_workspace_agent_config(p_workspace_id,
  a.configuration || jsonb_build_object('runtime',jsonb_build_object('schemaVersion',2,'values',
  p_values || coalesce(a.configuration->'runtime'->'values','{}'::jsonb))),
  'runtime:initial-environment-snapshot',0);
 RETURN true;
END $$;
REVOKE ALL ON FUNCTION public.initialize_workspace_agent_configuration(uuid,jsonb) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.initialize_workspace_agent_configuration(uuid,jsonb) TO service_role;

ON CONFLICT(key) DO NOTHING;
NOTIFY pgrst, 'reload schema';
