INSERT INTO public.agent_configuration_catalog(key,definition) VALUES
('maxReplyChars','{"key": "maxReplyChars", "label": "Tamanho máximo da resposta", "description": "Limite de caracteres da resposta final.", "type": "integer", "group": "Respostas", "min": 300, "max": 4000, "step": 100, "target": "setting", "attribute": "max_reply_chars", "default": 900, "readOnly": false}'::jsonb),
('historyTurns','{"key": "historyTurns", "label": "Turnos no histórico", "description": "Quantidade de mensagens anteriores enviadas ao modelo.", "type": "integer", "group": "Contexto", "min": 4, "max": 40, "step": 1, "target": "setting", "attribute": "agent_history_limit", "default": 12, "readOnly": false}'::jsonb),
('catalogShortlistSize','{"key": "catalogShortlistSize", "label": "Produtos apresentados", "description": "Máximo de opções mostradas ao cliente por resposta.", "type": "integer", "group": "Catálogo", "min": 1, "max": 5, "step": 1, "target": "setting", "attribute": "agent_revalidate_top_n", "default": 3, "readOnly": false}'::jsonb),
('catalogCandidatePool','{"key": "catalogCandidatePool", "label": "Candidatos de busca", "description": "Quantidade de produtos avaliados antes do ranqueamento.", "type": "integer", "group": "Catálogo", "min": 5, "max": 80, "step": 5, "target": "setting", "attribute": "agent_candidate_pool_limit", "default": 20, "readOnly": false}'::jsonb),
('catalogRerankLimit','{"key": "catalogRerankLimit", "label": "Candidatos para reranking", "description": "Quantidade de produtos enviados para a seleção final.", "type": "integer", "group": "Catálogo", "min": 5, "max": 20, "step": 1, "target": "setting", "attribute": "agent_rerank_selection_limit", "default": 15, "readOnly": false}'::jsonb),
('observabilityLevel','{"key": "observabilityLevel", "label": "Nível dos logs", "description": "Detalhado amplia diagnósticos, mantendo a redação de dados sensíveis.", "type": "select", "group": "Observabilidade", "options": [{"value": "standard", "label": "Padrão"}, {"value": "detailed", "label": "Detalhado"}], "target": "runtime", "attribute": null, "default": "standard", "readOnly": false}'::jsonb),
('learningEnabled','{"key": "learningEnabled", "label": "Revisar atendimentos", "description": "Permite que o NSAgent transforme sinais dos atendimentos em propostas de aprendizado.", "type": "boolean", "group": "Aprendizado", "target": "runtime", "attribute": "agent_learning_enabled", "default": true, "readOnly": false}'::jsonb),
('learningAutoPromote','{"key": "learningAutoPromote", "label": "Criar instruções automaticamente", "description": "Cria extensões pendentes a partir de insights aprovados pela constituição do agente.", "type": "boolean", "group": "Aprendizado", "target": "setting", "attribute": "agent_learning_auto_promote", "default": false, "readOnly": false}'::jsonb),
('learningAutoActivate','{"key": "learningAutoActivate", "label": "Ativação automática", "description": "Permite ativação sem gate humano. Mantenha desligado para revisão operacional.", "type": "boolean", "group": "Aprendizado", "target": "setting", "attribute": "agent_learning_auto_activate", "default": false, "readOnly": false}'::jsonb),
('learningLookbackHours','{"key": "learningLookbackHours", "label": "Janela de análise", "description": "Horas consideradas ao iniciar ou recompor o ciclo de aprendizado.", "type": "integer", "group": "Aprendizado", "min": 1, "max": 168, "step": 1, "target": "setting", "attribute": "agent_learning_lookback_hours", "default": 24, "readOnly": false}'::jsonb),
('learningBatchLimit','{"key": "learningBatchLimit", "label": "Atendimentos por ciclo", "description": "Limite de respostas avaliadas em cada execução do aprendizado.", "type": "integer", "group": "Aprendizado", "min": 50, "max": 2000, "step": 50, "target": "setting", "attribute": "agent_learning_batch_limit", "default": 500, "readOnly": false}'::jsonb),
('learningMaxClusters','{"key": "learningMaxClusters", "label": "Problemas por ciclo", "description": "Máximo de grupos de falha enviados para reflexão em cada ciclo.", "type": "integer", "group": "Aprendizado", "min": 1, "max": 20, "step": 1, "target": "setting", "attribute": "agent_learning_max_clusters", "default": 5, "readOnly": false}'::jsonb),
('learningCanaryHours','{"key": "learningCanaryHours", "label": "Duração do canário", "description": "Tempo de observação de uma instrução ativada automaticamente.", "type": "integer", "group": "Canário e rollback", "min": 1, "max": 72, "step": 1, "target": "setting", "attribute": "agent_learning_canary_hours", "default": 6, "readOnly": false}'::jsonb),
